BEGIN;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
DO $verify$
DECLARE c uuid:=gen_random_uuid();foreign_c uuid:=gen_random_uuid();admin uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();owner uuid:=gen_random_uuid();other_owner uuid:=gen_random_uuid();e uuid:=gen_random_uuid();draft uuid:=gen_random_uuid();tier uuid:=gen_random_uuid();t1 uuid:=gen_random_uuid();t2 uuid:=gen_random_uuid();unpaid uuid:=gen_random_uuid();req uuid:=gen_random_uuid();req2 uuid:=gen_random_uuid();cancel_req uuid:=gen_random_uuid();super_actor uuid:=gen_random_uuid();global_draft uuid:=gen_random_uuid();campus_draft uuid:=gen_random_uuid();r jsonb;b jsonb;bank jsonb:='{"account_number":"0123456789","bank_name":"Audit bank","account_name":"Audit organizer"}';n integer;
BEGIN
 INSERT INTO public.campuses(id,name,slug) VALUES(c,'[AUDIT rollback] Organizer','audit-organizer-'||c),(foreign_c,'[AUDIT rollback] Foreign','audit-organizer-'||foreign_c);
 INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT id,'audit-organizer-'||id||'@example.invalid','{}'::jsonb FROM unnest(ARRAY[admin,outsider,owner,other_owner,super_actor]) AS ids(id);
 UPDATE public.profiles SET campus_id=c,role='admin' WHERE id=admin;
 UPDATE public.profiles SET campus_id=foreign_c,role='admin' WHERE id=outsider;
 UPDATE public.profiles SET campus_id=NULL,role='super_admin' WHERE id=super_actor;
 r:=public.hg_organizer_event_draft(super_actor,global_draft,'create',jsonb_build_object('title','Global draft','location','Global','starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','capacity',20));IF r->>'campus_id' IS NOT NULL THEN RAISE EXCEPTION 'super admin global draft is campus bound';END IF;
 r:=public.hg_organizer_event_draft(super_actor,campus_draft,'create',jsonb_build_object('title','Campus draft','location','FUTA','starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','capacity',20,'campus_id',c));IF (r->>'campus_id')::uuid<>c THEN RAISE EXCEPTION 'super admin selected campus ignored';END IF;
 UPDATE public.profiles SET campus_id=c,role='event_organizer' WHERE id IN(owner,other_owner);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',admin)::text,true);PERFORM set_config('role','authenticated',true);
 UPDATE public.profiles SET role='student' WHERE id=other_owner;UPDATE public.profiles SET role='event_organizer' WHERE id=other_owner;GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'campus admin organizer appointment failed';END IF;
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.hg_organizer_event_draft(owner,e,'create',jsonb_build_object('title','Organizer draft','location','FUTA','starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','capacity',20));
 IF r->>'review_status'<>'draft' OR (r->>'is_published')::boolean THEN RAISE EXCEPTION 'draft was published';END IF;
 r:=public.hg_organizer_event_draft(owner,e,'submit');
 IF r->>'review_status'<>'submitted' THEN RAISE EXCEPTION 'submission not saved';END IF;
 r:=public.hg_review_organizer_event(admin,e,'changes_requested','{"notes":"Private organizer feedback"}');
 b:=public.hg_organizer_event_balance(owner,e);IF b#>>'{event,review_notes}'<>'Private organizer feedback' THEN RAISE EXCEPTION 'private review feedback missing';END IF;
 r:=public.hg_organizer_event_draft(owner,e,'submit');
 BEGIN PERFORM public.hg_review_organizer_event(owner,e,'approve');RAISE EXCEPTION 'organizer self-approved';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hg_organizer_event_draft(other_owner,e,'edit','{}');RAISE EXCEPTION 'other owner edited draft';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.events SET is_paid=true WHERE id=e;
 INSERT INTO public.event_ticket_tiers(id,event_id,name,price_naira,capacity,campus_id) VALUES(tier,e,'Regular',1600,20,c);
 BEGIN PERFORM public.hg_review_organizer_event(admin,e,'approve');RAISE EXCEPTION 'missing agreed amount approved';EXCEPTION WHEN check_violation THEN NULL;END;
 r:=public.hg_review_organizer_event(admin,e,'configure',jsonb_build_object('organizer_id',owner,'tiers',jsonb_build_array(jsonb_build_object('id',tier,'organizer_amount',1500))));
 r:=public.hg_review_organizer_event(admin,e,'approve');
 INSERT INTO public.event_tickets(id,event_id,tier_id,is_guest,guest_email,status,payment_status,campus_id,card_amount_used) VALUES(t1,e,tier,true,'audit-organizer-one@example.invalid','confirmed','paid',c,1600);
 UPDATE public.event_ticket_tiers SET price_naira=1800 WHERE id=tier;
 r:=public.hg_review_organizer_event(admin,e,'configure',jsonb_build_object('organizer_id',owner,'tiers',jsonb_build_array(jsonb_build_object('id',tier,'organizer_amount',1700))));
 INSERT INTO public.event_tickets(id,event_id,tier_id,is_guest,guest_email,status,payment_status,campus_id,card_amount_used) VALUES(t2,e,tier,true,'audit-organizer-two@example.invalid','confirmed','paid',c,1800),(unpaid,e,tier,true,'audit-organizer-unpaid@example.invalid','pending_payment','pending',c,1800);
 b:=public.hg_organizer_event_balance(owner,e);IF (b->>'earned')::numeric<>3200 OR (b->>'available')::numeric<>3200 THEN RAISE EXCEPTION 'earned balance uses listing price/holds or rewrote snapshot: %',b;END IF;
 BEGIN UPDATE hg_internal.event_ticket_earnings SET organizer_amount=1 WHERE ticket_id=t1;RAISE EXCEPTION 'earned snapshot changed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hg_review_organizer_event(admin,e,'configure',jsonb_build_object('organizer_id',other_owner));RAISE EXCEPTION 'issued owner changed';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN PERFORM public.hg_organizer_event_balance(other_owner,e);RAISE EXCEPTION 'other organizer saw settlement';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hg_organizer_event_balance(outsider,e);RAISE EXCEPTION 'foreign admin saw settlement';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.feature_flags(feature_name,campus_id,is_active) VALUES('events',c,true),('hp_multiplier',c,false);
 r:=public.hg_admit_event_ticket(e,t1,owner,NULL,c,0);IF NOT (r->>'completed')::boolean THEN RAISE EXCEPTION 'owner admission failed';END IF;
 r:=public.hg_admit_event_ticket(e,t1,owner,NULL,c,0);IF NOT (r->>'replayed')::boolean THEN RAISE EXCEPTION 'owner duplicate admission failed';END IF;
 BEGIN PERFORM public.hg_admit_event_ticket(e,t2,other_owner,NULL,c,0);RAISE EXCEPTION 'other organizer admitted ticket';EXCEPTION WHEN raise_exception THEN IF SQLERRM='other organizer admitted ticket' THEN RAISE;END IF;END;
 BEGIN PERFORM public.hg_event_payout_action(owner,e,req,'request',bank);RAISE EXCEPTION 'payout before event completion';EXCEPTION WHEN check_violation THEN NULL;END;
 -- Privileged fixture clock setup, not a production rescheduling action.
 PERFORM set_config('hg.event_operation',e::text,true);
 UPDATE public.events SET starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' WHERE id=e;
 PERFORM set_config('hg.event_operation','',true);
 r:=public.hg_event_payout_action(owner,e,cancel_req,'request',bank);
 r:=public.hg_event_payout_action(owner,e,cancel_req,'cancel');r:=public.hg_event_payout_action(owner,e,cancel_req,'cancel');IF r->>'state'<>'cancelled' THEN RAISE EXCEPTION 'cancel replay failed';END IF;
 r:=public.hg_event_payout_action(owner,e,req,'request',bank);IF (r->>'amount')::numeric<>3200 THEN RAISE EXCEPTION 'request amount not authoritative';END IF;
 r:=public.hg_event_payout_action(owner,e,req,'request',bank);IF (SELECT count(*) FROM hg_internal.event_payout_requests WHERE id=req)<>1 THEN RAISE EXCEPTION 'duplicate payout request';END IF;
 BEGIN PERFORM public.hg_event_payout_action(owner,e,gen_random_uuid(),'request',bank);RAISE EXCEPTION 'reserved balance spent twice';EXCEPTION WHEN check_violation THEN NULL;END;
 UPDATE public.event_tickets SET status='cancelled',payment_status='refund_pending' WHERE id=t1;
 BEGIN PERFORM public.hg_event_payout_action(admin,e,req,'approve');RAISE EXCEPTION 'refund-reduced balance approved';EXCEPTION WHEN check_violation THEN NULL;END;
 r:=public.hg_event_payout_action(admin,e,req,'reject','{"notes":"Refund changed available balance"}');
 r:=public.hg_event_payout_action(owner,e,req2,'request',bank);IF (r->>'amount')::numeric<>1700 THEN RAISE EXCEPTION 'refund balance incorrect';END IF;
 BEGIN PERFORM public.hg_event_payout_action(owner,e,req2,'approve');RAISE EXCEPTION 'owner approved own payout';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.hg_event_payout_action(admin,e,req2,'approve');
 BEGIN PERFORM public.hg_event_payout_action(admin,e,req2,'paid','{}');RAISE EXCEPTION 'transfer reference omitted';EXCEPTION WHEN check_violation THEN NULL;END;
 r:=public.hg_event_payout_action(admin,e,req2,'paid','{"reference":"AUDIT-BANK-ONE"}');
 r:=public.hg_event_payout_action(admin,e,req2,'paid','{"reference":"AUDIT-BANK-ONE"}');
 b:=public.hg_organizer_event_balance(owner,e);IF (b->>'paid')::numeric<>1700 OR (b->>'available')::numeric<>0 THEN RAISE EXCEPTION 'payout receipt re-applied';END IF;
 UPDATE public.event_tickets SET status='cancelled',payment_status='refunded' WHERE id=t2;
 b:=public.hg_organizer_event_balance(owner,e);IF (b->>'overpaid')::numeric<>1700 THEN RAISE EXCEPTION 'later refund hid settlement overpayment';END IF;
 r:=public.hg_organizer_event_draft(owner,draft,'create',jsonb_build_object('title','Private draft','location','FUTA','starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','capacity',20));
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND ((table_name='events' AND column_name IN('review_notes','reviewed_by','submitted_at')) OR (table_name='event_ticket_tiers' AND column_name='organizer_amount') OR (table_name='event_tickets' AND column_name IN('organizer_amount_snapshot','organizer_id_snapshot')))) THEN RAISE EXCEPTION 'private organizer fields remain public';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',owner)::text,true);PERFORM set_config('role','authenticated',true);
 SELECT count(*) INTO n FROM public.events WHERE id=draft;IF n<>1 THEN RAISE EXCEPTION 'own draft read blocked';END IF;
 UPDATE public.events SET is_published=true WHERE id=draft;GET DIAGNOSTICS n=ROW_COUNT;IF n<>0 THEN RAISE EXCEPTION 'organizer directly published draft';END IF;
 BEGIN PERFORM public.hg_organizer_event_balance(owner,e);RAISE EXCEPTION 'browser invoked privileged finance helper';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM 1 FROM hg_internal.event_payout_requests;RAISE EXCEPTION 'browser read private payouts';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('role','none',true);PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',other_owner)::text,true);PERFORM set_config('role','authenticated',true);
 SELECT count(*) INTO n FROM public.events WHERE id=draft;IF n<>0 THEN RAISE EXCEPTION 'foreign draft exposed';END IF;
 PERFORM set_config('role','none',true);
END $verify$;
ROLLBACK;
SELECT 'PASS: own drafts/review/financial terms, immutable per-ticket entitlement, no hold income, own check-in replay, private settlement requests/approval/payment receipts, refund recheck and overpayment visibility; no real transfer' AS evidence;
